class RobotPet:
    """A robot pet with a battery level that must stay between 0 and 100."""

    def __init__(self, name, battery, mood):
        self.name = name
        self.battery = max(0, min(100, battery))
        self.mood = mood

    def charge(self, amount):
        self.battery = max(0, min(100, self.battery + amount))
        return self.battery

    def show_talent(self):
        return f"{self.name} performs a generic trick!"


class RobotCat(RobotPet):
    def show_talent(self):
        return f"{self.name} chases a laser dot across the room!"


class RobotBird(RobotPet):
    def show_talent(self):
        return f"{self.name} whistles a cheerful tune!"


class RobotDog(RobotPet):
    def show_talent(self):
        return f"{self.name} fetches the ball and rolls over!"
